pragma solidity ^0.8.0;

contract Ownable {
    address public owner;

    constructor() {
        owner = msg.sender;
    }
}

function canWithdraw(uint256 requestedAmount) public view returns (bool) {
    if (requestedAmount <= balance) {
        return true;
    } else {
        return false;
    }
}

function totalOf(uint256[] memory amounts) public pure returns (uint256) {
    uint256 total = 0;
    for (uint256 i = 0; i < amounts.length; i++) {
        total += amounts[i];
    }
    return total;
}

